public int minimumDifference(int[] nums) {
    int n = nums.length / 2;
    int[] left = Arrays.copyOfRange(nums, 0, n);
    int[] right = Arrays.copyOfRange(nums, n, 2 * n);
    long total = 0;
    for (int x : nums) total += x;

    List<List<Integer>> leftSums = subsetSumsByCount(left);
    List<List<Integer>> rightSums = subsetSumsByCount(right);
    for (List<Integer> bucket : rightSums) Collections.sort(bucket);

    long best = Long.MAX_VALUE;
    for (int k = 0; k <= n; k++) {
        List<Integer> rs = rightSums.get(n - k);
        for (int ls : leftSums.get(k)) {
            long t = total - 2L * ls;   // want rs closest to t/2 -> minimize |t - 2*rs|
            best = Math.min(best, minAbs(rs, t));
        }
    }
    return (int) best;
}

private long minAbs(List<Integer> sorted, long t) {
    int lo = 0, hi = sorted.size();
    while (lo < hi) {                    // first index with 2*val >= t
        int mid = (lo + hi) >>> 1;
        if (2L * sorted.get(mid) >= t) hi = mid; else lo = mid + 1;
    }
    long best = Long.MAX_VALUE;
    if (lo < sorted.size()) best = Math.min(best, Math.abs(t - 2L * sorted.get(lo)));
    if (lo > 0)             best = Math.min(best, Math.abs(t - 2L * sorted.get(lo - 1)));
    return best;
}

private List<List<Integer>> subsetSumsByCount(int[] a) {
    int n = a.length;
    List<List<Integer>> res = new ArrayList<>();
    for (int i = 0; i <= n; i++) res.add(new ArrayList<>());
    for (int mask = 0; mask < (1 << n); mask++) {
        int cnt = Integer.bitCount(mask), sum = 0;
        for (int i = 0; i < n; i++) if ((mask & (1 << i)) != 0) sum += a[i];
        res.get(cnt).add(sum);
    }
    return res;
}

public int minAbsDifference(int[] nums, int goal) {
    int n = nums.length;
    int[] sa = allSubsetSums(Arrays.copyOfRange(nums, 0, n / 2));
    int[] sb = allSubsetSums(Arrays.copyOfRange(nums, n / 2, n));
    Arrays.sort(sb);

    int best = Integer.MAX_VALUE;
    for (int x : sa) {
        int t = goal - x;                         // want sb closest to t
        int lo = 0, hi = sb.length;
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (sb[mid] >= t) hi = mid; else lo = mid + 1; }
        if (lo < sb.length) best = Math.min(best, Math.abs(x + sb[lo] - goal));
        if (lo > 0)         best = Math.min(best, Math.abs(x + sb[lo - 1] - goal));
    }
    return best;
}

private int[] allSubsetSums(int[] a) {
    int n = a.length;
    int[] res = new int[1 << n];
    for (int mask = 1; mask < (1 << n); mask++) {
        int lsb = Integer.numberOfTrailingZeros(mask);
        res[mask] = res[mask & (mask - 1)] + a[lsb];   // reuse subset without lowest bit
    }
    return res;
}

public boolean subsetSum(int[] nums, long target) {
    int n = nums.length;
    long[] left = allSubsetSums(Arrays.copyOfRange(nums, 0, n / 2));
    long[] right = allSubsetSums(Arrays.copyOfRange(nums, n / 2, n));
    Arrays.sort(right);
    for (long x : left) {
        long need = target - x;
        int lo = 0, hi = right.length - 1;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (right[mid] == need) return true;
            else if (right[mid] < need) lo = mid + 1;
            else hi = mid - 1;
        }
    }
    return false;
}

