        int lsb = Integer.numberOfTrailingZeros(mask);
        res[mask] = res[mask & (mask - 1)] + a[lsb];
    }
    return res;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;
    int total = 0;
    for (int x : nums) total += x;

    int[] b = new int[n];
    for (int i = 0; i < n; i++) b[i] = nums[i] * n - total;   // need proper subset with sum(b)=0

    int half = n / 2, limit = n / 2;   // restrict subset size to [1, n/2]
    Set<Long> left = new HashSet<>();
    for (int mask = 0; mask < (1 << half); mask++) {
        int s = 0, cnt = 0;
        for (int i = 0; i < half; i++) if ((mask & (1 << i)) != 0) { s += b[i]; cnt++; }
        left.add(encode(s, cnt));
    }

    int rn = n - half;
    for (int mask = 0; mask < (1 << rn); mask++) {
        int s = 0, cnt = 0;
        for (int i = 0; i < rn; i++) if ((mask & (1 << i)) != 0) { s += b[half + i]; cnt++; }
        for (int k = 1; k <= limit; k++) {          // total subset size
            int need = k - cnt;
            if (need < 0) break;
            if (need > half) continue;
            if (left.contains(encode(-s, need))) return true;
        }
    }
    return false;
}

private long encode(int sum, int size) { return ((long) sum) * 64 + size; }

public List<Integer> countSmaller(int[] nums) {
    int n = nums.length;
    int[] sorted = nums.clone();
    Arrays.sort(sorted);
    int m = 0;
    int[] uniq = new int[n];
    for (int i = 0; i < n; i++) if (i == 0 || sorted[i] != sorted[i - 1]) uniq[m++] = sorted[i];

    BIT bit = new BIT(m);
    Integer[] res = new Integer[n];
    for (int i = n - 1; i >= 0; i--) {
        int rank = lowerBound(uniq, m, nums[i]) + 1;   // 1-based rank
        res[i] = bit.query(rank - 1);                  // ranks strictly below -> smaller values
        bit.update(rank, 1);
    }
    return Arrays.asList(res);
}

