        this.n = nums.length;
        this.nums = new int[n];
        this.tree = new int[n + 1];
        for (int i = 0; i < n; i++) update(i, nums[i]);
    }

    public void update(int index, int val) {
        int delta = val - nums[index];
        nums[index] = val;
        for (int i = index + 1; i <= n; i += i & (-i)) tree[i] += delta;
    }

    public int sumRange(int left, int right) {
        return prefix(right + 1) - prefix(left);
    }

    private int prefix(int i) {
        int s = 0;
        for (; i > 0; i -= i & (-i)) s += tree[i];
        return s;
    }
}

public int reversePairs(int[] nums) {
    int n = nums.length;
    long[] vals = new long[n];
    for (int i = 0; i < n; i++) vals[i] = nums[i];
    long[] sorted = Arrays.stream(vals).distinct().sorted().toArray();
    int m = sorted.length;

    BIT bit = new BIT(m);
    int count = 0, inserted = 0;
    for (int j = 0; j < n; j++) {
        long target = 2L * nums[j];
        int le = upperBound(sorted, target);      // # values <= target => ranks 1..le
        count += inserted - bit.query(le);        // inserted values strictly greater
        int rank = lowerBound(sorted, nums[j]) + 1;
        bit.update(rank, 1);
        inserted++;
    }
    return count;
}

