public int countRangeSum(int[] nums, int lower, int upper) {
    int n = nums.length;
    long[] pre = new long[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];

    long[] sorted = Arrays.stream(pre).distinct().sorted().toArray();
    int m = sorted.length;
    BIT bit = new BIT(m);

    int count = 0;
    bit.update(lowerBound(sorted, pre[0]) + 1, 1);   // insert P[0]
    for (int j = 1; j <= n; j++) {
        long lo = pre[j] - upper, hi = pre[j] - lower;
        int l = lowerBound(sorted, lo);              // first index with value >= lo
        int r = upperBound(sorted, hi);              // first index with value > hi
        count += bit.query(r) - bit.query(l);        // ranks (l+1..r) => values in [lo,hi]
        bit.update(lowerBound(sorted, pre[j]) + 1, 1);
    }
    return count;
}

