class MyCalendarThree {
    private static final int MAX = 1_000_000_000;
    private final Node root = new Node();

    public int book(int start, int end) {
        update(root, 0, MAX, start, end - 1, 1);
        return root.max;
    }

    private void update(Node node, int lo, int hi, int l, int r, int val) {
        if (r < lo || hi < l) return;
        if (l <= lo && hi <= r) { node.max += val; node.lazy += val; return; }
        pushDown(node);
        int mid = lo + (hi - lo) / 2;
        update(node.left, lo, mid, l, r, val);
        update(node.right, mid + 1, hi, l, r, val);
        node.max = Math.max(node.left.max, node.right.max);
    }

    private void pushDown(Node node) {
        if (node.left == null) node.left = new Node();
        if (node.right == null) node.right = new Node();
        if (node.lazy != 0) {
            node.left.max += node.lazy;  node.left.lazy += node.lazy;
            node.right.max += node.lazy; node.right.lazy += node.lazy;
            node.lazy = 0;
        }
    }

    private static class Node {
        Node left, right;
        int max, lazy;
    }
}

public int lengthOfLIS(int[] nums, int k) {
    int max = 0;
    for (int x : nums) max = Math.max(max, x);
    SegTree seg = new SegTree(max);      // values 1..max
    int ans = 0;
    for (int x : nums) {
        int lo = Math.max(1, x - k);
        int best = seg.query(lo, x - 1); // best dp for values in [x-k, x-1]
        int cur = best + 1;
        ans = Math.max(ans, cur);
        seg.update(x, cur);
    }
    return ans;
}

static class SegTree {
    int n;
    int[] tree;
    SegTree(int size) { n = size; tree = new int[4 * n]; }

    void update(int pos, int val) { update(1, 1, n, pos, val); }
    void update(int node, int lo, int hi, int pos, int val) {
        if (lo == hi) { tree[node] = Math.max(tree[node], val); return; }
        int mid = (lo + hi) >>> 1;
        if (pos <= mid) update(2 * node, lo, mid, pos, val);
        else            update(2 * node + 1, mid + 1, hi, pos, val);
        tree[node] = Math.max(tree[2 * node], tree[2 * node + 1]);
    }

    int query(int l, int r) { if (l > r) return 0; return query(1, 1, n, l, r); }
    int query(int node, int lo, int hi, int l, int r) {
        if (r < lo || hi < l) return 0;
        if (l <= lo && hi <= r) return tree[node];
        int mid = (lo + hi) >>> 1;
        return Math.max(query(2 * node, lo, mid, l, r), query(2 * node + 1, mid + 1, hi, l, r));
    }
}

public int[] maxSlidingWindow(int[] nums, int k) {
    int n = nums.length;
    int[] res = new int[n - k + 1];
    Deque<Integer> dq = new ArrayDeque<>();       // indices, values decreasing
    for (int i = 0; i < n; i++) {
        while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast();
        dq.offerLast(i);
        if (dq.peekFirst() <= i - k) dq.pollFirst();
        if (i >= k - 1) res[i - k + 1] = nums[dq.peekFirst()];
    }
    return res;
}

public int shortestSubarray(int[] nums, int k) {
    int n = nums.length;
    long[] prefix = new long[n + 1];
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];
    int res = n + 1;
    Deque<Integer> dq = new ArrayDeque<>();       // prefix indices, prefix values increasing
    for (int i = 0; i <= n; i++) {
        while (!dq.isEmpty() && prefix[i] - prefix[dq.peekFirst()] >= k)
            res = Math.min(res, i - dq.pollFirst());
        while (!dq.isEmpty() && prefix[dq.peekLast()] >= prefix[i]) dq.pollLast();
        dq.offerLast(i);
    }
    return res <= n ? res : -1;
}

public int constrainedSubsetSum(int[] nums, int k) {
    int n = nums.length;
    int[] dp = new int[n];
    Deque<Integer> dq = new ArrayDeque<>();       // indices, dp values decreasing
    int res = Integer.MIN_VALUE;
    for (int i = 0; i < n; i++) {
        while (!dq.isEmpty() && dq.peekFirst() < i - k) dq.pollFirst();
        int best = dq.isEmpty() ? 0 : Math.max(0, dp[dq.peekFirst()]);
        dp[i] = nums[i] + best;
        res = Math.max(res, dp[i]);
        while (!dq.isEmpty() && dp[dq.peekLast()] <= dp[i]) dq.pollLast();
        dq.offerLast(i);
    }
    return res;
}

public int maxResult(int[] nums, int k) {
    int n = nums.length;
    int[] dp = new int[n];
    dp[0] = nums[0];
    Deque<Integer> dq = new ArrayDeque<>();       // indices, dp values decreasing
    dq.offerLast(0);
    for (int i = 1; i < n; i++) {
        while (!dq.isEmpty() && dq.peekFirst() < i - k) dq.pollFirst();
        dp[i] = nums[i] + dp[dq.peekFirst()];
        while (!dq.isEmpty() && dp[dq.peekLast()] <= dp[i]) dq.pollLast();
        dq.offerLast(i);
    }
    return dp[n - 1];
}

public int largestRectangleArea(int[] heights) {
    int n = heights.length;
    Deque<Integer> stack = new ArrayDeque<>();    // indices, heights increasing
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int h = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && heights[stack.peek()] >= h) {
            int height = heights[stack.pop()];
            int left = stack.isEmpty() ? -1 : stack.peek();
            int width = i - left - 1;
            maxArea = Math.max(maxArea, height * width);
        }
        stack.push(i);
    }
    return maxArea;
}

public int findMaxValueOfEquation(int[][] points, int k) {
    Deque<int[]> dq = new ArrayDeque<>();         // {y - x, x}, first value decreasing
    int res = Integer.MIN_VALUE;
    for (int[] p : points) {
        int x = p[0], y = p[1];
        while (!dq.isEmpty() && dq.peekFirst()[1] < x - k) dq.pollFirst();
        if (!dq.isEmpty()) res = Math.max(res, dq.peekFirst()[0] + y + x);
        while (!dq.isEmpty() && dq.peekLast()[0] <= y - x) dq.pollLast();
        dq.offerLast(new int[]{y - x, x});
    }
    return res;
}

public int minMeetingRooms(int[][] intervals) {
    int n = intervals.length;
    int[] starts = new int[n];
    int[] ends = new int[n];
    for (int i = 0; i < n; i++) { starts[i] = intervals[i][0]; ends[i] = intervals[i][1]; }
    Arrays.sort(starts);
    Arrays.sort(ends);
    int rooms = 0, maxRooms = 0, e = 0;
    for (int s = 0; s < n; s++) {
        while (e < n && ends[e] <= starts[s]) { rooms--; e++; }
        rooms++;
        maxRooms = Math.max(maxRooms, rooms);
    }
    return maxRooms;
}

class MyCalendar {                                     // I: no double booking
    private final TreeMap<Integer, Integer> cal = new TreeMap<>(); // start -> end
    public boolean book(int start, int end) {
        Integer prev = cal.floorKey(start);
        Integer next = cal.ceilingKey(start);
        if (prev != null && cal.get(prev) > start) return false;
        if (next != null && next < end) return false;
        cal.put(start, end);
        return true;
    }
}

class MyCalendarTwo {                                  // II: no triple booking
    private final TreeMap<Integer, Integer> delta = new TreeMap<>();
    public boolean book(int start, int end) {
        delta.merge(start, 1, Integer::sum);
        delta.merge(end, -1, Integer::sum);
        int active = 0;
        for (int v : delta.values()) {
            active += v;
            if (active >= 3) {                         // would triple-book: roll back
                delta.merge(start, -1, Integer::sum);
                delta.merge(end, 1, Integer::sum);
                return false;
            }
        }
        return true;
    }
}

